const express = require('express');
const mysql = require('mysql2');
const cors = require('cors');

const app = express();
app.use(cors());
app.use(express.json());

// 1. Conexión física a tu base de datos de MySQL Workbench
const db = mysql.createConnection({
    host: 'localhost',
    user: 'root',             // Tu usuario habitual de Workbench
    password: 'tu_password',  // Cambia esto por tu contraseña real de MySQL
    database: 'torneo_futbol_db'
});

db.connect((err) => {
    if (err) {
        console.error('Error conectando a MySQL:', err);
        return;
    }
    console.log('¡Conectado exitosamente a torneo_futbol_db!');
});

// 2. Ruta para contar los datos del Dashboard del administrador
app.get('/api/dashboard/stats', (req, res) => {
    const consultas = {
        partidos: 'SELECT COUNT(*) AS total FROM partidos',
        equipos: 'SELECT COUNT(*) AS total FROM equipos',
        torneos: 'SELECT COUNT(*) AS total FROM torneos',
        jugadores: 'SELECT COUNT(*) AS total FROM jugadores'
    };

    // Consultamos todo al mismo tiempo de manera eficiente
    db.query(consultas.partidos, (e1, r1) => {
        db.query(consultas.equipos, (e2, r2) => {
            db.query(consultas.torneos, (e3, r3) => {
                db.query(consultas.jugadores, (e4, r4) => {
                    if (e1 || e2 || e3 || e4) {
                        return res.status(500).json({ error: "Fallo en las consultas" });
                    }
                    // Enviamos los totales calculados reales al Frontend
                    res.json({
                        partidos: r1[0].total,
                        equipos: r2[0].total,
                        torneos: r3[0].total,
                        jugadores: r4[0].total
                    });
                });
            });
        });
    });
});

// 3. Encender el puente en el puerto 3000
app.listen(3000, () => {
    console.log('Servidor del torneo escuchando en http://localhost:3000');
});